defaultSpec = {
				"specType": None, 
				"tolerance": {"lcl": None, "ldl": None, "lel": None, "lsl": None, "tgt": None, "ucl": None, "udl": None, "uel": None, "usl": None},
				"setPoint": {"operator": None, "value": None},
				"range": {"min": None, "max": None},
				"regex": {'value': ''}
				}

defaultPickList = {
					'pickListId': None,
					'pickListValues': {
										'Number': {'increment': None, 'min': None, 'max': None},
										'Fraction': {'increment': None, 'min': None, 'max': None},
										'Text': {'PASS': [], 'WARNING': [], 'FAIL': [], 'NEUTRAL': [], 'multiSelect': False},
										'Boolean': {'TRUE': ['OK'], 'FALSE': ['Not OK'], 'enableNA': False},
										'Barcode Scanner': {'script': None},
										'Time': None,
										'Tree': ''
									},
					}

checkConfig = system.util.jsonDecode(value)

if checkConfig is None:
	checkConfig = {
					'dataTypeId': None,
					'engUnitId': None,
					'specInfo': defaultSpec,
					'pickListInfo': defaultPickList
				}
elif not checkConfig['pickListInfo']['pickListValues']['Boolean'].has_key('enableNA'): checkConfig['pickListInfo']['pickListValues']['Boolean']['enableNA'] = False

return checkConfig

security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureProcedures']['enabled']: 
		canCreate = True
		canEdit = True

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

